import ifcopenshell
model = ifcopenshell.open('/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind/project/20_survey/NDDC-A2_Federated_Model_2026.ifc')

# Get footprints or building entities
for w in model.by_type('IfcWall'):
    # Get Name
    name = w.Name or 'no name'
    # Try to get geometry representation
    try:
        shape = w.Representation
        if shape:
            for rep in shape:
                for item in rep:
                    if hasattr(item, 'Coordinates'):
                        print(f'Wall {name}: Coordinates type {type(item.Coordinates)}')
    except:
        pass

# Check for type definitions with elevation
for w in model.by_type('IfcWallStandardCase'):
    name = w.Name or 'no name'
    print(f'Wall standard case: {name}')
"
